--liquibase formatted sql

--changeset icqchat:003-test-users
-- Test users for a quick start, password for both: password123
-- Hashes are generated by PostgreSQL (pgcrypto) in bcrypt format, compatible with the backend.
CREATE EXTENSION IF NOT EXISTS pgcrypto;

INSERT INTO users (login, password_hash) VALUES
    ('alice', crypt('password123', gen_salt('bf', 10))),
    ('bob', crypt('password123', gen_salt('bf', 10)))
ON CONFLICT (login) DO NOTHING;
--rollback DELETE FROM users WHERE login IN ('alice', 'bob');
